import "core-js/modules/es.array.push.js";
import SnackBar from "@/components/SnackBar.vue";
import DeleteCategories from "@/components/SloatBooking/Popups/DeleteCategories.vue";
import { slot_category } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  components: {
    SnackBar,
    DeleteCategories
  },
  data() {
    return {
      SnackBarComponent: {},
      categoriesdeletion: false,
      tableLoading: false,
      componentCheck: 0,
      categoriesItem: {},
      categoriesHeaders: [{
        title: "Name",
        value: "slot_category_name",
        sortable: false
      }, {
        title: "Created By",
        value: "slot_category_created_by_name",
        sortable: false
      }, {
        title: "Actions",
        value: "actions",
        sortable: false
      }],
      categoriesRecords: [],
      fixed: false,
      currentPage: 1,
      itemsPerPage: 20,
      pageCount: 1,
      windowHeight: 0
    };
  },
  computed: {
    paginatedItems() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return this.categoriesRecords.slice(start, end);
    },
    visiblePages() {
      const pages = [];
      const start = Math.max(1, this.currentPage - 2);
      const end = Math.min(this.pageCount, this.currentPage + 2);
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  async created() {
    await this.fetch_categories();
  },
  mounted() {
    this.windowHeight = window.innerHeight - 280;
  },
  methods: {
    get_date(val) {
      const d = new Date(parseInt(val));
      var date = d.getDate().toLocaleString();
      var month = (d.getMonth() + 1).toLocaleString();
      var year = d.getFullYear();
      return (+date <= 9 ? "0" + date : date) + "/" + (+month <= 9 ? "0" + month : month) + "/" + year;
    },
    open_deleteDailog(item) {
      this.categoriesItem = item;
      this.componentCheck = 1;
      this.categoriesdeletion = true;
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.categoriesdeletion = false;
      this.fetch_categories();
    },
    async fetch_categories() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(slot_category, {
          input: {
            organization_id: data.organization.organization_id,
            user_email_id: data.user.user_email_id,
            action_type: "LIST"
          }
        }));
        var response = JSON.parse(result.data.slot_category);
        this.categoriesRecords = [];
        this.tableLoading = false;
        if (response.Status == "SUCCESS") {
          this.categoriesRecords = response.data;
          this.tableLoading = false;
          this.pageCount = Math.ceil(this.categoriesRecords.length / this.itemsPerPage);
        } else {
          this.categoriesRecords = [];
          this.tableLoading = false;
        }
      } catch (error) {
        this.categoriesRecords = [];
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    updatePageItems(newPage) {
      this.currentPage = newPage;
    }
  }
};
